import { createHash } from "node:crypto";
import type { Journey } from "@finx/journey-schema";
import type { Brand, BrandDef } from "@finx/ui-kit";

export { zip, crc32 } from "./zip";

/**
 * How a generated file may be changed:
 * - generated: Studio rewrites it every time the project is exported. Do not edit it; change it in Studio.
 * - extendable: created once. After that it is yours and a later export will not overwrite it.
 * - custom: yours from the start. Studio never touches it.
 */
export type Tag = "generated" | "extendable" | "custom";
export type GeneratedFile = { path: string; content: string; tag: Tag; /** short note shown beside the file */ note?: string };
export type ProjectInput = {
  project: BrandDef & { id: string };
  brand: Brand;
  /** The journeys of this project. `journey` is what is written: the live version when there is one, else the draft. */
  journeys: { journey: Journey; live: boolean }[];
  studioUrl: string;
};

const json = (v: unknown) => JSON.stringify(v, null, 2) + "\n";
const en = (t: unknown): string => (typeof t === "string" ? t : (t as any)?.en ?? "");
export const sha = (s: string) => createHash("sha256").update(s).digest("hex").slice(0, 12);

/** The source of a project (its configuration, journeys and theme) as a folder of files a developer can read, review and keep in Git. */
export function generateProject(input: ProjectInput): GeneratedFile[] {
  const { project, brand, studioUrl } = input;
  const journeys = [...input.journeys].sort((a, b) => a.journey.slug.localeCompare(b.journey.slug));
  const { id, ...def } = project;
  const files: GeneratedFile[] = [];
  const add = (path: string, content: string, tag: Tag, note?: string) => files.push({ path, content, tag, note });

  add("README.md", readme(input, journeys), "extendable", "Start here");
  add("finx.project.json", json({ id, ...def }), "generated", "The project's identity and look");
  add(".env.example", `# Where the app loads published journeys from\nEXPO_PUBLIC_FINX_STUDIO_URL=${studioUrl}\n# Which project the app is built as\nEXPO_PUBLIC_FINX_BRAND=${id}\n`, "extendable");
  add("theme/tokens.json", json({ light: brand.light, dark: brand.dark, radius: brand.radius }), "generated", "Colours worked out from the accent, light and dark");
  for (const { journey, live } of journeys) {
    add(`journeys/${journey.slug}.json`, json(journey), "generated", `${en(journey.name)} · ${live ? `live v${journey.version}` : "draft, not published"}`);
  }
  add("src/journeys.ts", journeysModule(journeys.map((j) => j.journey.slug)), "generated", "Loads the journeys with their types");
  add("src/custom/README.md", `# Your code\n\nPut your own screens, custom blocks and adapters here. Studio never reads or rewrites this folder.\n`, "custom");

  const manifest = {
    project: id, generator: "FinX Studio",
    files: files.map((f) => ({ path: f.path, tag: f.tag, hash: sha(f.content) })),
    journeys: journeys.map((j) => ({ slug: j.journey.slug, version: j.journey.version, live: j.live })),
  };
  add(".finx/manifest.json", json(manifest), "generated", "What was generated, with checksums");
  return files;
}

function journeysModule(slugs: string[]): string {
  const ident = (s: string) => "j_" + s.replace(/[^a-zA-Z0-9]/g, "_");
  return [
    "// Generated by FinX Studio. Do not edit: change the journey in Studio and export again.",
    'import type { Journey } from "@finx/journey-schema";',
    ...slugs.map((s) => `import ${ident(s)} from "../journeys/${s}.json";`),
    "",
    `export const journeys = [${slugs.map(ident).join(", ")}] as unknown as Journey[];`,
    "",
  ].join("\n");
}

function readme({ project, journeys: _unused, studioUrl }: ProjectInput, journeys: ProjectInput["journeys"]): string {
  const id = project.id;
  const live = journeys.filter((j) => j.live).length;
  return `# ${project.name}

The source of the **${project.name}** app (${project.bundleId}), exported from FinX Studio.

- ${journeys.length} journey${journeys.length === 1 ? "" : "s"} (${live} live) in \`journeys/\`
- Look: ${project.preset} preset, accent ${project.accent}, ${project.currency}. The colours are in \`theme/tokens.json\`
- Studio: ${studioUrl}

## Use it

1. **Register the app.** Add \`finx.project.json\` to the FinX platform repository's \`packages/ui-kit/src/brands.json\` under the key \`${id}\`, without the \`id\` field. Put the app icons in the folder named by \`assets\`.
2. **Journeys.** Published journeys reach the running app over the air from Studio, with no new release. The files in \`journeys/\` are the same journeys, for review in Git and as the offline copies bundled in the app.
3. **Run or build it** from the platform repository:

\`\`\`bash
EXPO_PUBLIC_FINX_BRAND=${id} pnpm --filter @finx/bank-app web
pnpm ios:sim --brand ${id} --install
pnpm android:apk --brand ${id} --install
\`\`\`

## Files

Every file has a tag (see \`.finx/manifest.json\`):

| Tag | Meaning |
|---|---|
| generated | Studio rewrites it on every export. Change it in Studio instead of by hand |
| extendable | Created once. After that it is yours |
| custom | Yours from the start, in \`src/custom/\`. Studio never touches it |

This export does not include the app shell, the renderer or the native projects: those come from the FinX platform repository and its build scripts.
`;
}
